package com.hgame.games

import com.hgame.engine.Game

enum class Category(val label: String) {
    ARCADE("Arcade"), PUZZLE("Trí tuệ"), BOARD("Cờ & bàn"), CARD("Bài"),
    ACTION("Hành động"), SPORTS("Thể thao"), RACING("Đua xe"), CASUAL("Giải trí"),
}

class GameInfo(
    val id: String,
    val title: String,
    val tagline: String,
    val category: Category,
    val emoji: String,
    val color1: Long,
    val color2: Long,
    val factory: () -> Game,
) {
    val bestMode by lazy { factory().bestMode }
}

